/* Academy HTB - Dark Theme */

html,
body {
    background-color: #000000 !important;
    color: #e0e0e0 !important;
}

/* Main containers */
.container,
.container-fluid,
main,
section,
.content,
.card,
.panel {
    background-color: #000000 !important;
    color: #e0e0e0 !important;
}

/* Navigation */
nav,
.navbar,
header {
    background-color: #080808 !important;
    color: #ffffff !important;
}

/* Text */
h1, h2, h3, h4, h5, h6,
p, span, label, li {
    color: #e0e0e0;
}

/* Links */
a {
    color: #00bfff !important;
}

/* Inputs */
input,
textarea,
select {
    background-color: #111111 !important;
    color: #ffffff !important;
    border: 1px solid #333333 !important;
}

/* Buttons */
button,
.btn {
    background-color: #151515 !important;
    color: #ffffff !important;
    border-color: #333333 !important;
}

/* Tables */
table,
th,
td {
    background-color: #080808 !important;
    color: #e0e0e0 !important;
    border-color: #333333 !important;
}

/* Borders */
.card,
.panel {
    border-color: #222222 !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #000000;
}

::-webkit-scrollbar-thumb {
    background: #333333;
}


/* Academy HTB - Dark Red Inline Code */

/* Inline code and highlighted text */
code,
pre code,
p code,
li code,
[class*="highlight"] code {
    color: #8b0000 !important;
    background-color: #151515 !important;
    border-color: #330000 !important;
}

/* Inline code links */
a code,
code a,
p a code {
    color: #a00000 !important;
}

/* Text links */
a {
    color: #990000 !important;
}

/* Hover effect */
a:hover,
a code:hover {
    color: #cc0000 !important;
}

/* Code blocks */
pre,
.hljs {
    background-color: #080808 !important;
    border: 1px solid #292929 !important;
}

/* Keep code readable */
pre code {
    color: #b22222 !important;
}

/* Academy inline highlighted text */
.markdown code,
.content code,
article code {
    color: #8b0000 !important;
    background: #151515 !important;
}


/* =====================================
   Academy HTB - Dark Red Text Selection
   ===================================== */

/* Selected text */
::selection {
    color: #ffcccc !important;
    background-color: #8b0000 !important;
}

/* Firefox selection */
::-moz-selection {
    color: #ffcccc !important;
    background-color: #8b0000 !important;
}

/* Selected text inside code */
code::selection,
pre::selection {
    color: #ffffff !important;
    background-color: #a00000 !important;
}

code::-moz-selection,
pre::-moz-selection {
    color: #ffffff !important;
    background-color: #a00000 !important;
}

:root {
    color-scheme: dark !important;
    --z-red: #e21d38;
    --z-bg: #080809;
    --z-panel: #101012;
    --z-panel-2: #151316;
    --z-line: #29272b;
    --z-text: #eeeae6;
    --z-muted: #88858d;
    --color-primary: #e21d38 !important;
    --color-primary-hover: #ff304b !important;
  }

  html, body, #root, #app, main {
    background-color: var(--z-bg) !important;
    color: var(--z-text) !important;
  }

  body, button, input, textarea, select {
    color: var(--z-text);
  }

  header, nav, aside, [role="navigation"],
  [class*="sidebar"], [class*="Sidebar"],
  [class*="navbar"], [class*="Navbar"],
  [class*="header"], [class*="Header"] {
    border-color: var(--z-line) !important;
  }

  [class*="card"], [class*="Card"],
  [class*="panel"], [class*="Panel"],
  [class*="modal"], [class*="Modal"],
  [class*="dropdown"], [class*="Dropdown"],
  [class*="popover"], [class*="Popover"] {
    background-color: var(--z-panel) !important;
    border-color: var(--z-line) !important;
    box-shadow: none !important;
  }

  button, [role="button"], a,
  [class*="button"], [class*="Button"] {
    transition: color .15s ease, background-color .15s ease, border-color .15s ease !important;
  }

  a, [class*="link"], [class*="Link"] {
    color: var(--z-text);
  }

  a:hover, [class*="link"]:hover, [class*="Link"]:hover {
    color: var(--z-red) !important;
  }

  button[class*="primary"], [class*="primaryButton"],
  [class*="PrimaryButton"], [class*="btn-primary"] {
    background: var(--z-red) !important;
    border-color: var(--z-red) !important;
    color: #fff !important;
  }

  input, textarea, select, [role="textbox"] {
    background: #0c0c0e !important;
    border-color: #38343a !important;
    color: var(--z-text) !important;
    box-shadow: none !important;
  }

  ::selection { background: #e21d3866 !important; color: #fff !important; }

:root {
    color-scheme: dark !important;
    --z-red: #e21d38;
    --z-bg: #080809;
    --z-panel: #101012;
    --z-panel-2: #151316;
    --z-line: #29272b;
    --z-text: #eeeae6;
    --z-muted: #a09ba3;
    --main-surface-primary: #101012 !important;
    --main-surface-secondary: #151316 !important;
    --main-surface-tertiary: #1a181c !important;
    --sidebar-surface-primary: #0b0b0d !important;
    --border-light: #29272b !important;
    --text-primary: #eeeae6 !important;
    --text-secondary: #a09ba3 !important;
    --link: #e21d38 !important;
  }

  html, body {
    background: var(--z-bg) !important;
    color: var(--z-text) !important;
  }

  body, main, [role="main"],
  #thread, [data-testid*="conversation"] {
    color: var(--z-text);
  }

  nav, aside, [data-testid*="sidebar"],
  [class*="sidebar"], [class*="Sidebar"] {
    background-color: #0b0b0d !important;
    border-color: var(--z-line) !important;
  }

  article, [data-message-author-role],
  [data-testid*="conversation-turn"],
  [class*="prose"] {
    color: var(--z-text);
  }

  [data-message-author-role="assistant"] {
    background: transparent !important;
  }

  textarea, input, [contenteditable="true"],
  [data-testid="prompt-textarea"] {
    background-color: #101012 !important;
    color: var(--z-text) !important;
    border-color: #343037 !important;
    caret-color: var(--z-red) !important;
    box-shadow: none !important;
  }

  form:has([data-testid="prompt-textarea"]),
  [class*="composer"], [class*="Composer"] {
    border-color: var(--z-line) !important;
  }

  button, [role="button"] {
    transition: background-color .15s ease, border-color .15s ease, color .15s ease !important;
  }

  button:hover, [role="button"]:hover {
    border-color: #5a2731 !important;
  }

  a { color: #f05a6c; }
  a:hover { color: #ff8492 !important; }

  pre, code, [class*="code-block"] {
    background-color: #0c0c0e !important;
    border-color: var(--z-line) !important;
  }

  ::selection { background: #e21d3866 !important; color: #fff !important; }

:root {
    color-scheme: dark !important;
    --z-red: #e21d38;
    --z-bg: #080809;
    --z-panel: #101012;
    --z-panel-2: #151316;
    --z-line: #29272b;
    --z-text: #eeeae6;
    --z-muted: #a09ba3;
    --yt-spec-base-background: #080809 !important;
    --yt-spec-raised-background: #101012 !important;
    --yt-spec-menu-background: #101012 !important;
    --yt-spec-text-primary: #eeeae6 !important;
    --yt-spec-text-secondary: #a09ba3 !important;
    --yt-spec-10-percent-layer: #ffffff12 !important;
    --yt-spec-call-to-action: #e21d38 !important;
    --yt-spec-brand-button-background: #e21d38 !important;
    --yt-spec-brand-link-text: #f05a6c !important;
  }

  html, body, ytd-app, #content, #page-manager,
  ytd-browse, ytd-watch-flexy, #masthead-container {
    background-color: var(--z-bg) !important;
    color: var(--z-text) !important;
  }

  #masthead, ytd-masthead, #guide-content,
  ytd-mini-guide-renderer, tp-yt-paper-dialog,
  ytd-popup-container, ytd-menu-popup-renderer,
  ytd-multi-page-menu-renderer {
    background-color: #0b0b0d !important;
    border-color: var(--z-line) !important;
  }

  ytd-rich-item-renderer, ytd-video-renderer,
  ytd-compact-video-renderer, ytd-playlist-renderer,
  ytd-guide-entry-renderer, ytd-guide-section-renderer,
  ytd-watch-metadata, #secondary, #comments,
  ytd-comment-thread-renderer {
    background-color: transparent !important;
  }

  yt-chip-cloud-chip-renderer,
  yt-chip-cloud-chip-renderer[chip-style="STYLE_DEFAULT"],
  ytd-feed-filter-chip-bar-renderer {
    --yt-spec-button-chip-background: #151316 !important;
    --yt-spec-button-chip-text: #d7d2d5 !important;
  }

  ytd-searchbox, #search-form, #container.ytd-searchbox,
  input#search, ytd-masthead #search {
    background-color: #101012 !important;
    border-color: #343037 !important;
  }

  a, yt-formatted-string a { color: #f05a6c; }
  a:hover, yt-formatted-string a:hover { color: #ff8492 !important; }

  ytd-button-renderer[is-paper-button] #button,
  yt-button-shape button,
  ytd-subscribe-button-renderer button,
  #subscribe-button button {
    --yt-spec-button-chip-background: #e21d38 !important;
  }

  #progress, .ytp-play-progress, .ytp-swatch-background-color {
    background: var(--z-red) !important;
  }

  .ytp-menuitem:hover, tp-yt-paper-item:hover,
  ytd-menu-service-item-renderer:hover {
    background-color: #201116 !important;
  }

  ::selection { background: #e21d3866 !important; color: #fff !important; }
